function buildBrief(p, j) {
  const b = j.snapshot.board;
  const labels = {
    camera: "\uCE74\uBA54\uB77C\xB7\uAD6C\uB3C4",
    structure: "\uB9E4\uC2A4\xB7\uBCBD\uCCB4",
    openings: "\uCC3D\uD638\xB7\uAC1C\uAD6C\uBD80",
    furniture: "\uAC00\uAD6C \uBC30\uCE58"
  };
  return [
    "\uC6D0\uBCF8 3D \uC774\uBBF8\uC9C0\uB97C \uC2E4\uC0AC \uB290\uB08C\uC758 \uAC74\uCD95 \uC0AC\uC9C4\uC73C\uB85C \uD3B8\uC9D1\uD55C\uB2E4.",
    j.baseResultId ? "\uC120\uD0DD \uACB0\uACFC\uB97C \uC218\uC815\uD558\uB418 \uC6D0\uBCF8 3D \uC774\uBBF8\uC9C0\uB294 \uD615\uD0DC \uAE30\uC900\uC73C\uB85C \uC720\uC9C0\uD55C\uB2E4." : "\uC6D0\uBCF8 3D \uC774\uBBF8\uC9C0\uAC00 \uD3B8\uC9D1 \uB300\uC0C1\uC774\uC790 \uD615\uD0DC \uAE30\uC900\uC774\uB2E4.",
    `\uC720\uC9C0 \uC870\uAC74: ${Object.entries(b.preserve).filter(([, v]) => v).map(([k]) => labels[k]).join(", ") || "\uC0AC\uC6A9\uC790 \uC9C0\uC2DC\uB97C \uB530\uB984"}.`,
    `\uC804\uCCB4 \uBC29\uD5A5: ${b.direction}`,
    `\uCD94\uAC00 \uC694\uCCAD: ${j.instruction}`,
    ...b.items.map((item, i) => {
      const r = j.snapshot.references.find((r2) => r2.id === item.referenceId);
      const auto = item.roles.includes("auto");
      const roles = auto ? "\uC790\uB3D9 \u2014 \uC2E4\uC81C \uCC38\uC870 \uC774\uBBF8\uC9C0\uB97C \uBCF4\uACE0 \uC7AC\uB8CC\xB7\uC870\uBA85\xB7\uC0C9\uAC10\xB7\uC870\uACBD\xB7\uAC00\uAD6C\xB7\uBD84\uC704\uAE30 \uC911 \uC801\uD569\uD55C \uC694\uC18C\uC640 \uC801\uC6A9 \uB300\uC0C1\uC744 \uD310\uB2E8\uD55C\uB2E4. \uC804\uCCB4 \uBC29\uD5A5\uACFC \uC720\uC9C0 \uC870\uAC74\uC744 \uC6B0\uC120\uD558\uACE0 \uC0AC\uC6A9\uC790 \uBA54\uBAA8\uAC00 \uC788\uC73C\uBA74 \uB530\uB978\uB2E4" : item.roles.join(", ");
      return `\uCC38\uC870 ${i + 1} (${r.title}): \uC5ED\uD560=${roles}; \uB300\uC0C1=${item.target.trim() || "\uC6D0\uBCF8 \uACF5\uAC04\uC5D0 \uB9DE\uAC8C \uC790\uB3D9 \uD310\uB2E8"}; \uC9C0\uC2DC=${item.note.trim() || "\uC774\uBBF8\uC9C0\uC5D0\uC11C \uC801\uD569\uD55C \uD2B9\uC131\uC744 \uCD94\uCD9C"}. \uCC38\uC870\uC758 \uD615\uD0DC\uC640 \uCE74\uBA54\uB77C\uB294 \uAC00\uC838\uC624\uC9C0 \uC54A\uB294\uB2E4.`;
    }),
    "\uC2E4\uC81C \uC785\uB825 \uC774\uBBF8\uC9C0\uB97C \uBAA8\uB450 \uD655\uC778\uD558\uACE0 \uB0B4\uC7A5 \uC774\uBBF8\uC9C0 \uB3C4\uAD6C\uB9CC \uC0AC\uC6A9\uD55C\uB2E4. \uC774\uBBF8\uC9C0 \uC218 \uC81C\uD55C\uC774 \uC788\uC73C\uBA74 \uD544\uC218 \uCC38\uC870\uB97C \uC870\uC6A9\uD788 \uB204\uB77D\uD558\uC9C0 \uC54A\uB294\uB2E4.",
    "\uC0DD\uC131 \uB4A4 \uC6D0\uBCF8\uACFC \uBE44\uAD50\uD574 \uB208\uC5D0 \uBCF4\uC774\uB294 \uD615\uD0DC \uBCC0\uD654\uB97C \uAE30\uB85D\uD55C\uB2E4. \uCE58\uC218 \uC815\uD655\uB3C4\uB97C \uBCF4\uC7A5\uD558\uC9C0 \uC54A\uB294\uB2E4."
  ].join("\n");
}
export {
  buildBrief
};
